import Nav from "./components/Nav/Nav";
import Body from "./components/Body/Body";

import "./App.css";

function App() {
  function value(e) {
    e.preventDefault();
    const form = e.target;
    console.log(e.target.elements.city.value);
    form.reset();
  }
  return (
    <div>
      <Nav value={value}/>
      <Body />
    </div>
  );
}

export default App;
